"""Griffe extension that appends ' [checked]' to every collected function's docstring."""

import griffe


class CheckedDocstringExtension(griffe.Extension):
    """Appends ' [checked]' to the docstring of every function griffe collects."""

    def on_function(
        self,
        *,
        func: griffe.Function,
        loader: griffe.GriffeLoader,
        **kwargs,
    ) -> None:
        if func.docstring is not None:
            func.docstring.value = func.docstring.value + " [checked]"


extensions = griffe.load_extensions(CheckedDocstringExtension())

